```javascript
import * as THREE from 'three/webgpu';
import { texture, uv, uniform, vec3, vec4, mix, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const width = 1.4;
  const height = 0.42;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshStandardNodeMaterial({
    transparent: true,
    metalness: 0.4,
    roughness: 0.55,
  });

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const hoverUniform = uniform(0.0);
  const pressUniform = uniform(0.0);

  const accentColor = vec3(1.0, 0.1647, 0.2196); // #ff2a38
  const inkColor = vec3(0.0863, 0.0863, 0.1137); // #16161d
  const paperColor = vec3(0.9098, 0.9255, 0.9490); // #e8ecf2

  const vUv = uv();
  // edge factor: distance from left/right edges to create capsule edge glow
  const edgeDist = float(1.0).sub(
    smoothstep(0.0, 0.08, vUv.x).oneMinus().add(smoothstep(0.92, 1.0, vUv.x))
  ).oneMinus();

  const grain = texture(map, vUv);

  const baseColor = mix(inkColor, paperColor, grain.r.mul(0.15).add(0.85));
  const accentEdge = mix(baseColor, accentColor, edgeDist.mul(hoverUniform.mul(0.6).add(0.25)));

  material.colorNode = vec4(accentEdge, grain.a.mul(0.0).add(1.0));
  material.emissiveNode = accentColor.mul(hoverUniform.mul(0.35));

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 1.6, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.userData.baseY = mesh.position.y;

  const group = new THREE.Group();
  group.add(mesh);
  group.position.set(0, 0, 0);

  let hoverTl = null;
  let pressTl = null;

  const onHoverIn = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, {
      y: mesh.userData.baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(hoverUniform, {
      value: 1.0,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
  };

  const onHoverOut = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(mesh.position, {
      y: mesh.userData.baseY,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(hoverUniform, {
      value: 0.0,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
  };

  const onClick = () => {
    pressTl?.kill();
    pressTl = gsap.timeline();
    pressTl.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(mesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    });

    if (group.userData.emit) {
      group.userData.emit('hub-collection.select', { itemId: 'hub-collection' });
    }
  };

  group.userData.handlers = {
    pointerover: onHoverIn,
    pointerenter: onHoverIn,
    pointerout: onHoverOut,
    pointerleave: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();
    hoverTl = null;
    pressTl = null;
    geometry.dispose();
    material.dispose();
    map.dispose();
  };

  return group;
}
